// TideWall 3D — a Part II stage (Campaign → The Undertow): a lane of drained seabed between two standing walls of sea.
// The expedition walks in from the shore end, does what the stage asks (its Objectives), and leaves by the gate at
// the far end, on to the next stage's scene. Creatures step out of the water walls ahead of the expedition, faster
// while an objective stirs the sea up. The tide clock (the overdriven core holding the sea back) ends the run if it
// runs out. The team, its money and its levels travel between stages in the run's save.
//
// Generated by ExpeditionBuilder (TideWall → Rebuild Stages) into one scene per stage; edit those scenes in Unity.
using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using Random = UnityEngine.Random;

namespace TideWall
{
    public class Expedition : Level
    {
        [Header("Stage")]
        [Tooltip("Which stage of the assault part this scene plays (0-based)")] public int stageIndex;
        [Tooltip("Half the lane's width: the water walls stand here")] public float halfWidth = 24;
        public float length = 190;
        public Transform playerStart;
        [Tooltip("Where creatures step out of the water walls")] public List<Transform> creatureSpawns = new();
        public List<Objective> objectives = new();
        public ExitGate exit;
        [Tooltip("The Hull Graveyard: where the wrecks of earlier runs lie (one per run played)")] public Bounds memorialField;

        float tideLeft, spawnT = 4;
        bool cleared, warned, leaving;
        Vector3 checkpoint;
        readonly HashSet<int> outfitted = new();
        GameManager gm;

        public PartDef Part => gm.Campaign.parts.Find(p => p.kind == PartKind.Assault);
        public StageDef Stage { get { var s = Part.stages; return s[Mathf.Clamp(stageIndex, 0, s.Count - 1)]; } }
        public int StageIndex => stageIndex;
        public bool Cleared => cleared;
        public float TideLeft => tideLeft;
        /// <summary>Debug menu: the tide clock back to full.</summary>
        public void DebugRefillTide() => tideLeft = Stage.tideSeconds;
        bool LastStage => stageIndex >= Part.stages.Count - 1;

        /// <summary>From GameManager.Awake, before anything's Start (Begin and the HUD need the stage straight away).</summary>
        public override void Init(GameDatabase db) => gm = GameManager.I;

        void Start()
        {
            gm ??= GameManager.I;
            tideLeft = Stage.tideSeconds;
            checkpoint = playerStart ? playerStart.position : new Vector3(0, 0, 6);
            foreach (var o in objectives) if (o) o.Activate(this);
            PlaceMemorials();
            // The title card: the part's opening words before its first stage
            StoryCard.Stage(Part, stageIndex);
        }

        /// <summary>Host/offline: the stage begins (from GameManager.StartRun).</summary>
        public void Begin(SaveData save)
        {
            gm.Waves.Day = Stage.difficultyDay;
            tideLeft = Stage.tideSeconds;
        }

        // ------------------------------------------------------------------ the stage being played (host)
        protected override void Update()
        {
            base.Update();
            if (gm == null || gm.State != GameState.Playing || Net.IsClient || leaving) return;
            float dt = Time.deltaTime;

            // New arrivals start at the part's level (players from the last stage keep theirs)
            foreach (var p in gm.Players.All)
                if (p.Simulated && outfitted.Add(p.Index) && gm.Loaded?.players.Find(s => s.index == p.Index) == null) p.StartAtLevel(Part.startLevel);

            // The tide clock
            if (Stage.tideSeconds > 0)
            {
                tideLeft -= dt;
                if (!warned && tideLeft < 60) { warned = true; gm.Banner("THE TIDE IS TURNING", "One minute before the sea comes home."); Sfx.Play("horn"); }
                if (tideLeft <= 0) { gm.GameOver("The tide came home."); return; }
            }

            float pressure = 1;
            foreach (var o in objectives) if (o) { o.Tick(dt); pressure = Mathf.Max(pressure, o.Pressure); }

            // The sea answers: creatures step out of the walls ahead of the expedition
            spawnT -= dt * pressure;
            if (spawnT <= 0 && GameManager.Enemies.Count < Stage.maxAlive * Mathf.Min(1.6f, pressure) && gm.Players.All.Count > 0)
            {
                spawnT = Stage.spawnEvery * Random.Range(.7f, 1.3f);
                SpawnFromWalls();
            }
        }

        void SpawnFromWalls()
        {
            float near = float.MaxValue, far = float.MinValue;
            foreach (var p in gm.Players.All) if (!p.IsOut) { near = Mathf.Min(near, p.transform.position.z); far = Mathf.Max(far, p.transform.position.z); }
            if (near == float.MaxValue) return;
            var options = creatureSpawns.FindAll(t => t && t.position.z > near - 6 && t.position.z < far + 40);
            if (options.Count == 0) options = creatureSpawns;
            if (options.Count == 0) return;
            var at = options[Random.Range(0, options.Count)].position;
            SpawnNear(at, 1);
            Fx.Splash(at + Vector3.up, 10);
        }

        /// <summary>One creature from the stage's line-up near `pos` (spires hatch them too).</summary>
        public Enemy SpawnNear(Vector3 pos, float spread)
        {
            var pool = new List<EnemyDef>();
            float total = 0;
            foreach (var id in Stage.enemies) if (gm.DB.Enemy(id) is { } def) { pool.Add(def); total += Mathf.Max(.01f, def.spawnWeight); }
            if (pool.Count == 0) return null;
            float pick = Random.value * total;
            var chosen = pool[^1];
            foreach (var d in pool) { pick -= Mathf.Max(.01f, d.spawnWeight); if (pick <= 0) { chosen = d; break; } }
            var at = pos + new Vector3(Random.Range(-spread, spread), 0, Random.Range(-spread, spread));
            at.x = Mathf.Clamp(at.x, -halfWidth + 1.5f, halfWidth - 1.5f);
            return gm.Waves.SpawnExtra(chosen, at);
        }

        /// <summary>An objective was finished: the expedition regroups there, and the fallen get back up.</summary>
        public void ObjectiveDone(Objective o)
        {
            int done = objectives.FindAll(x => x && x.Done).Count, total = objectives.FindAll(x => x).Count;
            checkpoint = o.transform.position + new Vector3(0, 0, -6);
            checkpoint.x = Mathf.Clamp(checkpoint.x, -halfWidth + 3, halfWidth - 3);
            foreach (var p in gm.Players.All) if (p.Simulated && (p.IsOut || p.IsDowned)) p.Respawn(SpawnPoint(p.Index));
            if (done >= total) Clear();
            else gm.Banner(Stage.objective switch
            {
                ObjectiveKind.Spires => "A BROOD SPIRE FALLS",
                ObjectiveKind.Beacons => "A BEACON BURNS",
                _ => "DONE",
            }, $"{done} of {total}");
        }

        void Clear()
        {
            if (cleared) return;
            cleared = true;
            if (Stage.objective != ObjectiveKind.Heart)
            {
                exit?.SetOpen();
                gm.Banner("THE WAY IS OPEN", LastStage ? "" : $"Deeper: {Part.stages[stageIndex + 1].title}.");
            }
        }

        /// <summary>Host: through the gate, into the next stage, with the team and its save.</summary>
        public void NextStage()
        {
            if (leaving || Net.IsClient || LastStage) return;
            leaving = true;
            var save = SaveSystem.Capture(gm);
            save.stage = stageIndex + 1;
            if (gm.SaveSlot > 0) SaveSystem.Write(save);
            GameManager.Load(Part.stages[save.stage].scene, gm.Carry(save, gm.SaveSlot));
        }

        /// <summary>Host: the Heart was answered. Everyone sees the ending, then the expedition is over.</summary>
        public void Finish(string ending)
        {
            if (leaving) return;
            leaving = true;
            int level = 0, kills = 0;
            foreach (var p in gm.Players.All) { level = Mathf.Max(level, p.Level); kills += p.Kills; }
            Legacy.RecordExpedition(stageIndex, level, kills);
            if (gm.SaveSlot > 0) SaveSystem.Delete(gm.SaveSlot);
            if (Net.IsHost) Net.Host.Ending(ending);
            ShowEnding(ending, host: true);
        }

        /// <summary>Every machine: record the answer and play its ending; the host then takes everyone home.</summary>
        public static void ShowEnding(string ending, bool host)
        {
            Legacy.RecordEnding(ending);
            var gm = GameManager.I;
            StoryCard.Ending(gm.Campaign.Ending(ending), () =>
            {
                if (!host) return;   // clients go home when the host leaves
                Net.Shutdown("The expedition is over.");
                GameManager.Load(GameManager.MenuScene, null);
            });
        }

        // ------------------------------------------------------------------ the Hull Graveyard's memorials
        /// <summary>One wreck for every run this machine has played: you are not the first expedition.</summary>
        void PlaceMemorials()
        {
            if (memorialField.size.sqrMagnitude < 1) return;
            int n = Mathf.Min(30, Legacy.Load().Tally);
            var rng = new System.Random(7177);
            var root = new GameObject("Earlier expeditions").transform;
            root.SetParent(transform, false);
            for (int i = 0; i < n; i++)
            {
                var at = new Vector3(memorialField.min.x + (float)rng.NextDouble() * memorialField.size.x, 0, memorialField.min.z + (float)rng.NextDouble() * memorialField.size.z);
                var hull = ModelFactory.Spawn("WreckHull", root, at, .8f + (float)rng.NextDouble() * .5f);
                hull.root.transform.rotation = Quaternion.Euler((float)rng.NextDouble() * 30 - 15, (float)rng.NextDouble() * 360, (float)rng.NextDouble() * 50 + 10);
                Glyphs.Decal(hull.root.transform, "crest", new Vector3(.62f, 1.1f, 0), Quaternion.Euler(0, -90, 0), 1.1f, new Color(.9f, .85f, .7f, .65f));
                Glyphs.Decal(hull.root.transform, "tally", new Vector3(.62f, .5f, 1.2f), Quaternion.Euler(0, -90, 0), .6f, new Color(.9f, .85f, .7f, .5f));
            }
        }

        // ------------------------------------------------------------------ Level
        public override Vector3 Goal(Vector3 from, float radius, out GoalKind kind)
        {
            // Out here the creatures hunt: the nearest sailor within sight, or they hold their ground
            Player best = null; float bd = 60;
            foreach (var p in gm.Players.All)
            {
                if (!p.IsTargetable) continue;
                var d = p.transform.position - from; d.y = 0;
                if (d.magnitude < bd) { bd = d.magnitude; best = p; }
            }
            if (best != null) { kind = GoalKind.Hunt; return best.transform.position; }
            kind = GoalKind.Home;
            return from;
        }

        public override Vector3 FlyerTarget(Vector3 from)
        {
            var goal = Goal(from, 0, out var kind);
            return kind == GoalKind.Hunt ? goal + Vector3.up * 1.2f : from + Vector3.forward * 3 + Vector3.up * 3;
        }

        public override Vector3 SpawnPoint(int index) => checkpoint + new Vector3(-3 + index * 2, 0, 0);

        public override string BuildRule(Vector3 spot, float radius)
        {
            if (Mathf.Abs(spot.x) > halfWidth - radius - 1) return "Too close to the water";
            if (spot.z < 1 || spot.z > length - 1) return "Out of bounds";
            return null;
        }

        public override string StatusLine()
        {
            string what;
            if (cleared && Stage.objective != ObjectiveKind.Heart) what = "The way is open";
            else
            {
                int done = 0, total = 0; string current = null;
                foreach (var o in objectives) { if (!o) continue; total++; if (o.Done) done++; else current ??= o.Progress; }
                what = Stage.objective switch
                {
                    ObjectiveKind.Spires => $"{Stage.objectiveText}: {done}/{total}",
                    ObjectiveKind.Beacons => $"{Stage.objectiveText}: {done}/{total}" + (current != null ? $" ({current})" : ""),
                    _ => current != null ? $"{Stage.objectiveText}: {current}" : Stage.objectiveText,
                };
            }
            if (Stage.tideSeconds <= 0) return what;
            int s = Mathf.Max(0, Mathf.CeilToInt(tideLeft));
            string clock = $"{s / 60}:{s % 60:00}";
            return $"{what} · Tide {(tideLeft < 60 ? $"<color=#fca5a5>{clock}</color>" : clock)}";
        }

        public override float StatusFraction() => Stage.tideSeconds > 0 ? Mathf.Clamp01(tideLeft / Stage.tideSeconds) : 1;

        // ------------------------------------------------------------------ online
        public override void WriteNet(BinaryWriter w)
        {
            w.Write(tideLeft); w.Write(cleared);
            w.Write((byte)objectives.Count);
            foreach (var o in objectives) { w.Write(o != null); if (o) o.WriteNet(w); }
        }

        public override void ReadNet(BinaryReader r)
        {
            tideLeft = r.ReadSingle();
            bool c = r.ReadBoolean();
            int n = r.ReadByte();
            for (int i = 0; i < n; i++)
            {
                if (!r.ReadBoolean()) continue;
                if (i < objectives.Count && objectives[i]) objectives[i].ReadNet(r);
                else throw new InvalidDataException("the host's stage has different objectives");
            }
            if (c && !cleared) { cleared = true; if (Stage.objective != ObjectiveKind.Heart) exit?.SetOpen(); }
        }

        // ------------------------------------------------------------------ runs
        /// <summary>A save that starts (or continues) Part II at a stage.</summary>
        public static SaveData NewSave(GameManager gm, int slot, int stage)
        {
            var part = gm.Campaign.parts.Find(p => p.kind == PartKind.Assault);
            return new SaveData { slot = slot, part = part?.id ?? "undertow", stage = stage, sandDollars = part?.startSandDollars ?? 0 };
        }

        public static string SceneFor(Campaign campaign, SaveData save)
        {
            var part = campaign.Part(save.part) ?? campaign.parts.Find(p => p.kind == PartKind.Assault);
            return part.stages[Mathf.Clamp(save.stage, 0, part.stages.Count - 1)].scene;
        }
    }
}
